// Standard pagination page object.
export function pageInput(limit = 200, offset = 0) {
  return { paginateBy: 'OFFSET', limit, offset } as const
}

/**
 * The operators a storage filter can actually use — each one run against a real object and
 * confirmed to filter. Anything off this list 500s the read at run time, two ways:
 * `GREATER_THAN` / `LESS_THAN` cannot be mapped at all and die with a NullPointerException
 * (the real names are `GT` / `GTE` / `LT` / `LTE`), while `WITHIN`, `MIN_LENGTH` and
 * `MAX_LENGTH` map fine and then fail with no error message and no exception class —
 * nothing to debug from, so they are left out rather than documented as a footgun.
 */
export type FilterOperator =
  | 'EQUAL'
  | 'NOT_EQUAL'
  | 'IN'
  | 'NOT_IN'
  | 'GT'
  | 'GTE'
  | 'LT'
  | 'LTE'
  | 'BETWEEN'
  | 'CONTAINS'
  | 'NOT_CONTAINS'
  | 'ICONTAINS'
  | 'NOT_ICONTAINS'
  | 'STARTS_WITH'
  | 'NOT_STARTS_WITH'
  | 'ENDS_WITH'
  | 'NOT_ENDS_WITH'
  | 'REGEX'
  | 'NOT_REGEX'
  | 'IREGEX'
  | 'NOT_IREGEX'
  | 'EXISTS'
  | 'MISSING'

export type LeafFilter = {
  property: string
  filter: { operator: FilterOperator; value: unknown }
}

const leaf = (property: string, operator: FilterOperator, value: unknown): LeafFilter => ({
  property,
  filter: { operator, value },
})

/**
 * Comparison builders, so no call site has to spell the name: the platform calls them
 * `GT`-style, people guess `GREATER_THAN`, and a wrong guess 500s the read instead of
 * failing the build. Other operators are written as literals — `FilterOperator` rejects a
 * wrong name either way.
 */
export const gt = (property: string, value: string | number) => leaf(property, 'GT', value)
export const gte = (property: string, value: string | number) => leaf(property, 'GTE', value)
export const lt = (property: string, value: string | number) => leaf(property, 'LT', value)
export const lte = (property: string, value: string | number) => leaf(property, 'LTE', value)

/**
 * The storage node's filter is a FilterConditionsField, NOT the entity API's
 * `{op, field, values}` — that shape is accepted with a 200 and SILENTLY IGNORED
 * (verified: it returned all 32 records instead of the 8 that matched). `value` is
 * singular; a `values` array errors the workflow. `{}` means no filter.
 * Property paths: the record id is `id`, every schema field is `properties.<key>`.
 */
export function andFilter(leaves: LeafFilter[]) {
  if (leaves.length === 0) return {}
  return { operator: 'AND', filters: leaves }
}

/** The execute-node envelope: `{ lookupReferences, response: { cursor, total, objects, hasMore }, id }`. */
export type FetchPage<T> = { records: T[]; total: number; hasMore: boolean; cursor?: string }

/**
 * One stored row, flattened into the record the app actually uses.
 *
 * The wire shape nests every schema field: `{ id, properties: { title, status, … },
 * createdTime, modifiedTime, entityType, version, … }`. Generated apps read those
 * fields FLAT (`ticket.title`), and `useData<Ticket[]>` is an unchecked cast that
 * tells TypeScript they already are — so nothing catches the mismatch. The build is
 * green, the fetch succeeds, `data.length` is right, and every single cell renders
 * `undefined`. Flattening here is what makes `data` match the type it claims.
 *
 * Order is deliberate:
 *   * `id` is applied AFTER the spread. The filter contract reserves it for the RECORD
 *     id (`field: 'id'`, never `properties.id`), so a schema field of the same name
 *     must not shadow it.
 *   * `createdTime`/`modifiedTime` go BEFORE it. They are row metadata, so a schema
 *     field that happens to share the name is the one the app means.
 * The rest of the row's metadata (`entityType`, `version`, `deleted`, `ownerUserId`, …)
 * is dropped: it is storage bookkeeping, not app data, and merging it invites a
 * collision with a real field for no gain.
 *
 * A row with no `properties` object is already flat — a seed row, or a second pass —
 * and is returned untouched, which is what makes the extractors idempotent.
 */
function flattenRecord<T>(row: unknown): T {
  if (!row || typeof row !== 'object') return row as T
  const source = row as {
    id?: unknown
    properties?: unknown
    createdTime?: unknown
    modifiedTime?: unknown
  }
  const properties = source.properties
  if (!properties || typeof properties !== 'object' || Array.isArray(properties)) {
    return row as T
  }
  const meta: Record<string, unknown> = {}
  if (source.createdTime !== undefined) meta.createdTime = source.createdTime
  if (source.modifiedTime !== undefined) meta.modifiedTime = source.modifiedTime
  return { ...meta, ...(properties as Record<string, unknown>), id: source.id } as T
}

/**
 * A record you read, turned into a payload you can save. USE IT ON EVERY WRITE.
 *
 * `flattenRecord` adds `id`, `createdTime` and `modifiedTime` to every record so the
 * app can show when a row was made or last changed. None of the three is a field of
 * the object, and an update sends the WHOLE record — so they have to come back off.
 * Leave them on and the write is rejected outright: `additionalProperties: false`.
 *
 * The stamps belong to the server anyway. The one you read is the value from BEFORE
 * your edit, so sending it back would be wrong even where it is accepted.
 *
 * If the object has its own field named `id`/`createdTime`/`modifiedTime`, this drops
 * that field too — a flat record cannot tell the two apart. `read_object` says so when
 * an object is shaped that way; put the field back by hand at the call site.
 */
export function toPayload<T extends object>(record: T): Record<string, unknown> {
  // underscored because they are dropped, not read — oxlint errors on a plain name here
  const {
    id: _id,
    createdTime: _createdTime,
    modifiedTime: _modifiedTime,
    ...fields
  } = record as Record<string, unknown>
  return fields
}

/** The node's own output, with the `response` wrapper off if one is present.
 *
 * Every storage op is reached through the same `useExecuteWorkflowNode`, which wraps the
 * node's output in `response`. Unwrapping once here is what lets the four extractors
 * below describe the SHAPES rather than each re-deriving the wrapper. */
function nodeOutput(data: unknown): Record<string, unknown> | undefined {
  if (!data || typeof data !== 'object' || Array.isArray(data)) return undefined
  const envelope = data as Record<string, unknown>
  const inner = envelope.response
  if (inner && typeof inner === 'object' && !Array.isArray(inner)) {
    return inner as Record<string, unknown>
  }
  return envelope
}

export function extractPage<T>(data: unknown): FetchPage<T> {
  // ALREADY EXTRACTED. `useData` hands back the records array, and a wrapper that
  // extracts it a second time used to hit the throw below on the first row that
  // arrived — uncaught, blanking the page on a green build. An array is a shape we
  // recognise, so pass it through. (`total`/`hasMore` are gone by then; read them off
  // `useData` instead of re-deriving them here.)
  if (Array.isArray(data)) {
    const records = data.map((row) => flattenRecord<T>(row))
    return { records, total: records.length, hasMore: false }
  }
  const response = nodeOutput(data)
  if (!response || !Array.isArray(response.objects)) {
    // Loud, not empty. Returning [] here would render "no records" for a response whose
    // shape changed — the failure mode this whole data layer exists to avoid.
    throw new Error('unexpected fetch response: no response.objects')
  }
  // `cursor` is an OBJECT on the wire — `{next, previous}` per the node's output schema,
  // not a string. Reading it as a string silently returned undefined for every paged
  // fetch, so "load more" had nothing to send and paging stopped at page one.
  const rawCursor = response.cursor
  const cursor =
    typeof rawCursor === 'string'
      ? rawCursor
      : rawCursor && typeof rawCursor === 'object'
        ? ((rawCursor as { next?: unknown }).next as string | undefined)
        : undefined
  return {
    records: (response.objects as unknown[]).map((row) => flattenRecord<T>(row)),
    // NOTE: `fetch_records` does not return a grand total — its output schema is
    // `{objects, hasMore, cursor, innerHits}`. So this is the size of THIS PAGE whenever
    // the backend omits it, which is what it has always been. Do not render it as "N
    // records exist"; use it only against a single unpaged read.
    total: typeof response.total === 'number' ? response.total : response.objects.length,
    hasMore: response.hasMore === true,
    cursor,
  }
}

export function extractRecords<T>(data: unknown): T[] {
  return extractPage<T>(data).records
}

/** One record — from a SINGLE fetch, a CREATE, or an UPDATE.
 *
 * The three writes do NOT share an envelope, and that is not a quirk to paper over at
 * each call site — it is the whole reason this function exists. Per the nodes' own
 * output schemas (uacode `configs/workflow-nodes/storage_by_unifyapps/`):
 *
 *     create_record          { id, entityType, properties, version, … }   the record, BARE
 *     update_record_by_id    { success, object: { id, properties, … } }   NESTED under `object`
 *     delete_record_by_id    { success }                                  no record at all
 *     fetch_records          { objects: [...], hasMore, cursor }          a list
 *
 * UPDATE was the one that broke. `{success, object}` carries no `id` at the level this
 * checked, so it fell through to `extractPage`, found no `objects`, and THREW
 * `unexpected fetch response: no response.objects` — on a successful write. The record
 * had been saved; the hook reported a failure. */
export function extractRecord<T>(data: unknown): T | undefined {
  const response = nodeOutput(data)
  if (response) {
    // UPDATE: the record is under `object`, beside a `success` flag.
    const nested = response.object
    if (nested && typeof nested === 'object' && !Array.isArray(nested) && 'id' in nested) {
      return flattenRecord<T>(nested)
    }
    // CREATE, or a single FETCH: the record itself.
    if (!Array.isArray(response.objects) && 'id' in response) {
      return flattenRecord<T>(response)
    }
    // DELETE: `{success}` and nothing else. Not an error, and not a record.
    if (!('objects' in response) && 'success' in response) return undefined
  }
  return extractPage<T>(data).records[0]
}
